1	use std::collections::BTreeMap;
2	
3	/// One damaged item reported in an incident.
4	pub struct Damage {
5	    pub item_type: String,
6	    pub amount: i64,
7	}
8	
9	/// A damage report filed against an existing policy.
10	pub struct Incident {
11	    pub damages: Vec<Damage>,
12	}
13	
14	/// A scenario: the one customer the MHPCO deals with, and the steps they file.
15	pub struct Scenario {
16	    pub customer: Customer,
17	    pub steps: Vec<Step>,
18	}
19	
20	/// One operation the customer asks the MHPCO to perform.
21	pub enum Step {
22	    Quote {
23	        items: Vec<Item>,
24	    },
25	    Claim {
26	        /// Zero-based index of the quote step that created the policy.
27	        policy: usize,
28	        incident: Incident,
29	    },
30	}
31	
32	/// What the MHPCO reports for one step of a scenario.
33	#[derive(Debug)]
34	pub enum StepResult {
35	    Quote { premium: u64 },
36	    Claim { payout: u64, remaining_cap: u64 },
37	}
38	
39	/// Why the MHPCO refuses to process a scenario at all.
40	#[derive(Debug)]
41	pub enum ScenarioError {
42	    /// The step a claim named as its policy is no quote step, so it wrote no
43	    /// policy the claim could be settled against.
44	    NoPolicyAtStep { step: usize },
45	    Quote(QuoteError),
46	    Claim(ClaimError),
47	}
48	
49	impl std::fmt::Display for ScenarioError {
50	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
51	        match self {
52	            Self::NoPolicyAtStep { step } => {
53	                write!(formatter, "step {step} created no policy to claim against")
54	            }
55	            Self::Quote(error) => error.fmt(formatter),
56	            Self::Claim(error) => error.fmt(formatter),
57	        }
58	    }
59	}
60	
61	/// Why the MHPCO refuses to quote a premium at all.
62	#[derive(Debug)]
63	pub enum QuoteError {
64	    /// The catalogue lists no item of this type.
65	    UnknownItemType { item_type: String },
66	}
67	
68	impl std::fmt::Display for QuoteError {
69	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
70	        match self {
71	            Self::UnknownItemType { item_type } => {
72	                write!(formatter, "the MHPCO does not insure a {item_type}")
73	            }
74	        }
75	    }
76	}
77	
78	/// Why the MHPCO refuses to settle a claim at all.
79	#[derive(Debug)]
80	pub enum ClaimError {
81	    /// A damage was reported with a negative amount.
82	    NegativeDamageAmount { amount: i64 },
83	    /// The policy covers no item of this type at all.
84	    ItemNotInsured { item_type: String },
85	    /// More damages of this item type were reported than the policy covers.
86	    MoreDamagesThanInsuredItems { item_type: String },
87	}
88	
89	impl std::fmt::Display for ClaimError {
90	    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
91	        match self {
92	            Self::NegativeDamageAmount { amount } => {
93	                write!(formatter, "a damage amount of {amount} is not a loss")
94	            }
95	            Self::ItemNotInsured { item_type } => {
96	                write!(formatter, "the damaged {item_type} is not insured by this policy")
97	            }
98	            Self::MoreDamagesThanInsuredItems { item_type } => write!(
99	                formatter,
100	                "more {item_type} damages were reported than the policy insures"
101	            ),
102	        }
103	    }
104	}
105	
106	/// What the MHPCO settles on a claim: the payout and the cap left on the
107	/// policy afterwards.
108	#[derive(Debug)]
109	pub struct ClaimResult {
110	    pub payout: u64,
111	    pub remaining_cap: u64,
112	}
113	
114	/// The single customer a scenario is quoted for.
115	pub struct Customer {
116	    pub years_with_mhpco: u32,
117	}
118	
119	pub struct Item {
120	    pub item_type: String,
121	    pub material: String,
122	    pub enchantment: u32,
123	    pub cursed: bool,
124	}
125	
126	const PROCESSING_FEE: u64 = 5;
127	const DEDUCTIBLE_PER_DAMAGE: u64 = 100;
128	const CAP_MULTIPLE_OF_INSURANCE_SUM: u64 = 2;
129	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL: u32 = 8;
130	const HALF_REIMBURSEMENT_PERCENT: u64 = 50;
131	
132	const COMPONENT_INSURANCE_VALUE: u64 = 250;
133	const COMPONENT_BASE_PREMIUM: u64 = 25;
134	const COMPONENT_BLOCK_BASE_PREMIUM: u64 = 60;
135	const COMPONENT_BLOCK_SIZE: usize = 3;
136	const CURSE_SURCHARGE_PERCENT: u64 = 50;
137	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT: u64 = 30;
138	const HIGH_ENCHANTMENT_LEVEL: u32 = 5;
139	const FIRST_INSURANCE_SURCHARGE_PERCENT: u64 = 10;
140	const LOYALTY_DISCOUNT_PERCENT: u64 = 20;
141	const LOYALTY_YEARS: u32 = 2;
142	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT: u64 = 15;
143	
144	/// Components, such as runes and moonstones, are the parts the MHPCO insures
145	/// alongside main items and the only items the building-block offer covers.
146	fn is_component(item: &Item) -> bool {
147	    matches!(item.item_type.as_str(), "rune" | "moonstone")
148	}
149	
150	/// What the MHPCO price list says about one main item: the value it is insured
151	/// for and the base premium it costs to insure. The list states both figures on
152	/// one line per item, and the office never learns one without the other.
153	struct PriceListEntry {
154	    insurance_value: u64,
155	    base_premium: u64,
156	}
157	
158	/// The MHPCO price list for main items, or nothing at all when the catalogue
159	/// does not list that type. This is the one place the roster of insurable main
160	/// items is written down: being listed here is what it means for the office to
161	/// insure a type.
162	fn price_list_entry(item_type: &str) -> Option<PriceListEntry> {
163	    let (insurance_value, base_premium) = match item_type {
164	        "sword" => (1000, 100),
165	        "amulet" => (600, 60),
166	        "staff" => (800, 80),
167	        "potion" => (400, 40),
168	        _ => return None,
169	    };
170	    Some(PriceListEntry {
171	        insurance_value,
172	        base_premium,
173	    })
174	}
175	
176	/// The MHPCO insures the components it recognises and the main items its price
177	/// list names; it insures nothing else.
178	fn is_in_catalogue(item: &Item) -> bool {
179	    is_component(item) || price_list_entry(&item.item_type).is_some()
180	}
181	
182	/// A reported damage must be a loss, never a negative amount.
183	fn check_every_damage_amount_is_a_loss(incident: &Incident) -> Result<(), ClaimError> {
184	    match incident.damages.iter().find(|damage| damage.amount < 0) {
185	        Some(negative) => Err(ClaimError::NegativeDamageAmount {
186	            amount: negative.amount,
187	        }),
188	        None => Ok(()),
189	    }
190	}
191	
192	/// The MHPCO can only price the items its catalogue lists.
193	fn check_every_item_is_in_the_catalogue(items: &[Item]) -> Result<(), QuoteError> {
194	    match items.iter().find(|item| !is_in_catalogue(item)) {
195	        Some(unknown) => Err(QuoteError::UnknownItemType {
196	            item_type: unknown.item_type.clone(),
197	        }),
198	        None => Ok(()),
199	    }
200	}
201	
202	/// The price-list line a main item is priced and insured by. The catalogue
203	/// guard has already refused anything the list does not name, so a main item
204	/// the office has accepted is always listed.
205	fn listed(item: &Item) -> PriceListEntry {
206	    price_list_entry(&item.item_type).expect("the catalogue lists this item type")
207	}
208	
209	/// The base premium one insured item earns. Every component is priced alike;
210	/// a main item is priced by its price-list line.
211	fn base_premium(item: &Item) -> u64 {
212	    if is_component(item) {
213	        return COMPONENT_BASE_PREMIUM;
214	    }
215	    listed(item).base_premium
216	}
217	
218	/// The building-block offer is reserved for a group of exactly 3 alike
219	/// components; a larger group does not qualify, it is priced per component.
220	fn qualifies_as_building_block(alike_component_count: usize) -> bool {
221	    alike_component_count == COMPONENT_BLOCK_SIZE
222	}
223	
224	/// The price the MHPCO charges for one group of alike components: the
225	/// building-block offer when the group qualifies, otherwise per component.
226	fn component_group_base_premium(count: usize) -> u64 {
227	    if qualifies_as_building_block(count) {
228	        COMPONENT_BLOCK_BASE_PREMIUM
229	    } else {
230	        count as u64 * COMPONENT_BASE_PREMIUM
231	    }
232	}
233	
234	/// How many entries fall under each key a list of items is grouped by. The
235	/// MHPCO tallies items this way wherever a rule counts like with like: the
236	/// claim side groups by catalogue type to match damages against cover, the
237	/// premium side by alike-group key to recognise a building block.
238	fn count_by_item_type<'a>(
239	    item_types: impl Iterator<Item = &'a str>,
240	) -> BTreeMap<&'a str, usize> {
241	    let mut counts: BTreeMap<&str, usize> = BTreeMap::new();
242	    for item_type in item_types {
243	        *counts.entry(item_type).or_insert(0) += 1;
244	    }
245	    counts
246	}
247	
248	/// Two components are "alike" when they share this key. For the MHPCO,
249	/// alike means the very same catalogue type: a rune and a moonstone are
250	/// never alike, so mixed component types form no building block.
251	fn alike_group_key(item: &Item) -> &str {
252	    &item.item_type
253	}
254	
255	/// The policy base premium: the sum of all insured items' base premiums,
256	/// with alike components priced per group so a block can be recognised.
257	fn policy_base_premium(items: &[Item]) -> u64 {
258	    let main_items_total: u64 = items
259	        .iter()
260	        .filter(|item| !is_component(item))
261	        .map(base_premium)
262	        .sum();
263	
264	    let alike_component_groups = count_by_item_type(
265	        items
266	            .iter()
267	            .filter(|item| is_component(item))
268	            .map(alike_group_key),
269	    );
270	
271	    main_items_total
272	        + alike_component_groups
273	            .values()
274	            .map(|count| component_group_base_premium(*count))
275	            .sum::<u64>()
276	}
277	
278	/// Who owes an amount, which is what decides the direction the MHPCO rounds it.
279	#[derive(Clone, Copy)]
280	enum Debtor {
281	    Customer,
282	    Mhpco,
283	}
284	
285	/// Every amount is rounded to whole G in the MHPCO's favor. That one rule
286	/// settles the direction by itself once it is known who owes whom: an amount
287	/// the customer owes is rounded up, an amount the office owes is rounded down.
288	/// Intermediate amounts stay fractional; only the final amount is rounded.
289	fn rounded_in_mhpco_favor(amount: f64, owed_by: Debtor) -> u64 {
290	    match owed_by {
291	        Debtor::Customer => amount.ceil() as u64,
292	        Debtor::Mhpco => amount.floor() as u64,
293	    }
294	}
295	
296	/// A policy-wide modifier is measured against the policy base premium, the
297	/// sum of all item base premiums, never against a single item.
298	fn percent_of_policy_base(policy_base_premium: f64, percent: u64) -> f64 {
299	    policy_base_premium * percent as f64 / 100.0
300	}
301	
302	/// Every item in a quote is treated as a first insurance, so the initial
303	/// assessment surcharge is charged on the whole policy base premium.
304	fn first_insurance_surcharge(policy_base_premium: f64) -> f64 {
305	    percent_of_policy_base(policy_base_premium, FIRST_INSURANCE_SURCHARGE_PERCENT)
306	}
307	
308	/// The MHPCO charges a high-enchantment risk surcharge on items it considers
309	/// highly enchanted. This is the premium-side threshold; the claim-side
310	/// reimbursement clause judges enchantment by its own, stricter threshold.
311	fn is_highly_enchanted(item: &Item) -> bool {
312	    item.enchantment >= HIGH_ENCHANTMENT_LEVEL
313	}
314	
315	/// An item-specific risk surcharge is charged on the base premium of the
316	/// affected item, never on the policy total.
317	fn risk_surcharge_on_base_premium(item: &Item, surcharge_percent: u64) -> f64 {
318	    base_premium(item) as f64 * surcharge_percent as f64 / 100.0
319	}
320	
321	/// The risk surcharge one item carries. Risks the MHPCO recognises stack: an
322	/// item that brings two of them is surcharged for each.
323	fn item_risk_surcharge(item: &Item) -> f64 {
324	    let mut surcharge = 0.0;
325	    if item.cursed {
326	        surcharge += risk_surcharge_on_base_premium(item, CURSE_SURCHARGE_PERCENT);
327	    }
328	    if is_highly_enchanted(item) {
329	        surcharge += risk_surcharge_on_base_premium(item, HIGH_ENCHANTMENT_SURCHARGE_PERCENT);
330	    }
331	    surcharge
332	}
333	
334	/// Item-specific modifiers apply to the base premium of the affected item,
335	/// never to the policy total, so the policy owes the sum of the items' own
336	/// risk surcharges.
337	fn item_risk_surcharges(items: &[Item]) -> f64 {
338	    items.iter().map(item_risk_surcharge).sum()
339	}
340	
341	/// A long-standing customer, with at least two years of business with the
342	/// MHPCO, has earned the loyalty discount.
343	fn is_long_standing(customer: &Customer) -> bool {
344	    customer.years_with_mhpco >= LOYALTY_YEARS
345	}
346	
347	/// The loyalty discount is a policy-wide modifier, so it is measured against
348	/// the policy base premium.
349	fn loyalty_discount(customer: &Customer, policy_base_premium: f64) -> f64 {
350	    if is_long_standing(customer) {
351	        percent_of_policy_base(policy_base_premium, LOYALTY_DISCOUNT_PERCENT)
352	    } else {
353	        0.0
354	    }
355	}
356	
357	/// A contract is a follow-up when the customer already holds at least one
358	/// other contract with the MHPCO; the customer's very first is not.
359	fn is_follow_up_contract(contracts_already_held: u32) -> bool {
360	    contracts_already_held > 0
361	}
362	
363	/// Every contract after the customer's first earns the follow-up discount. It
364	/// is a policy-wide modifier, so it is measured against the policy base premium.
365	fn follow_up_contract_discount(contracts_already_held: u32, policy_base_premium: f64) -> f64 {
366	    if is_follow_up_contract(contracts_already_held) {
367	        percent_of_policy_base(policy_base_premium, FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)
368	    } else {
369	        0.0
370	    }
371	}
372	
373	/// What the customer's standing with the MHPCO adds to or takes off the policy
374	/// base premium: the net of every policy-wide surcharge and discount. Positive
375	/// amounts raise the premium, negative amounts lower it.
376	fn policy_wide_modifiers(
377	    customer: &Customer,
378	    contracts_already_held: u32,
379	    policy_base_premium: f64,
380	) -> f64 {
381	    first_insurance_surcharge(policy_base_premium)
382	        - loyalty_discount(customer, policy_base_premium)
383	        - follow_up_contract_discount(contracts_already_held, policy_base_premium)
384	}
385	
386	/// The premium the policy earns before the processing fee: the policy base
387	/// premium, plus what the items' own risks cost, plus what the customer's
388	/// standing adjusts.
389	fn modified_policy_premium(
390	    customer: &Customer,
391	    contracts_already_held: u32,
392	    items: &[Item],
393	) -> f64 {
394	    let policy_base_premium = policy_base_premium(items) as f64;
395	    policy_base_premium
396	        + item_risk_surcharges(items)
397	        + policy_wide_modifiers(customer, contracts_already_held, policy_base_premium)
398	}
399	
400	/// The MHPCO adds its processing fee to every premium at the very end, after
401	/// every surcharge and discount has been settled.
402	pub fn quote_premium(
403	    customer: &Customer,
404	    contracts_already_held: u32,
405	    items: &[Item],
406	) -> Result<u64, QuoteError> {
407	    check_every_item_is_in_the_catalogue(items)?;
408	    Ok(rounded_in_mhpco_favor(
409	        modified_policy_premium(customer, contracts_already_held, items) + PROCESSING_FEE as f64,
410	        Debtor::Customer,
411	    ))
412	}
413	
414	/// Damage to a very highly enchanted item is reimbursed at only half the
415	/// damage amount. This claim-side threshold is deliberately stricter than, and
416	/// separate from, the premium-side high-enchantment risk surcharge: an item can
417	/// be enchanted enough to cost more to insure yet not enough to be halved.
418	fn is_reimbursed_by_half(item: &Item) -> bool {
419	    item.enchantment >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL
420	}
421	
422	/// How much of a reported damage the MHPCO's reimbursement clauses cover,
423	/// before the deductible is taken off. Full reimbursement is the MHPCO's
424	/// standing position: it is both what an item with no clause receives and what
425	/// the dragon-material clause prescribes, so that clause asks for no share of
426	/// its own. Only the halving clause departs from full reimbursement, and it
427	/// wins wherever it applies.
428	fn covered_damage(damaged_item: &Item, damage: &Damage) -> f64 {
429	    if is_reimbursed_by_half(damaged_item) {
430	        damage.amount as f64 * HALF_REIMBURSEMENT_PERCENT as f64 / 100.0
431	    } else {
432	        damage.amount as f64
433	    }
434	}
435	
436	/// The deductible applies per damage event, after the reimbursement clauses.
437	fn reimbursement_for(damaged_item: &Item, damage: &Damage) -> f64 {
438	    (covered_damage(damaged_item, damage) - DEDUCTIBLE_PER_DAMAGE as f64).max(0.0)
439	}
440	
441	/// Which insured item a reported damage refers to. A damage names only a
442	/// catalogue type, so the policy is searched for an item of that type; the
443	/// reimbursement clauses are judged against the item found here, not the report.
444	fn insured_item_for<'a>(items: &'a [Item], damage: &Damage) -> &'a Item {
445	    items
446	        .iter()
447	        .find(|item| item.item_type == damage.item_type)
448	        .expect("the damaged item is insured by this policy")
449	}
450	
451	/// What the MHPCO owes for an incident filed against a policy: the sum of the
452	/// reimbursements its damages earn, rounded in the office's favor at the end.
453	/// This is the tally inside a settlement, not an operation of its own: it knows
454	/// nothing of admissibility or of the cap, so only `claim` may speak for it.
455	fn claim_payout(items: &[Item], incident: &Incident) -> u64 {
456	    let total: f64 = incident
457	        .damages
458	        .iter()
459	        .map(|damage| reimbursement_for(insured_item_for(items, damage), damage))
460	        .sum();
461	    rounded_in_mhpco_favor(total, Debtor::Mhpco)
462	}
463	
464	/// What one insured item is insured for. Every component is insured alike; a
465	/// main item is insured for the value its price-list line names.
466	fn insurance_value(item: &Item) -> u64 {
467	    if is_component(item) {
468	        return COMPONENT_INSURANCE_VALUE;
469	    }
470	    listed(item).insurance_value
471	}
472	
473	/// The insurance sum of a policy is the sum of its items' insurance values.
474	fn insurance_sum(items: &[Item]) -> u64 {
475	    items.iter().map(insurance_value).sum()
476	}
477	
478	/// The total payout per policy is capped at twice the insurance sum.
479	fn policy_cap(items: &[Item]) -> u64 {
480	    CAP_MULTIPLE_OF_INSURANCE_SUM * insurance_sum(items)
481	}
482	
483	/// How the cap limits one settlement: the MHPCO pays what the incident earned,
484	/// but never more than the cap the policy has left, and reports the cap that
485	/// survives the payout.
486	fn settled_within_cap(earned: u64, available_cap: u64) -> ClaimResult {
487	    let payout = earned.min(available_cap);
488	    ClaimResult {
489	        payout,
490	        remaining_cap: available_cap - payout,
491	    }
492	}
493	
494	/// How much of its cap a policy still has to pay out with, once earlier claims
495	/// have drawn on it. A cap can be drawn down until it is exhausted, and an
496	/// exhausted cap is simply nothing left, never a debt the policy owes back.
497	fn cap_remaining_on(items: &[Item], cap_already_consumed: u64) -> u64 {
498	    policy_cap(items).saturating_sub(cap_already_consumed)
499	}
500	
501	/// How many items of a catalogue type a policy insures. A type the policy never
502	/// mentions is insured none of: the MHPCO holds no cover for what it did not
503	/// write down.
504	fn insured_count_of(insured_counts: &BTreeMap<&str, usize>, item_type: &str) -> usize {
505	    insured_counts.get(item_type).copied().unwrap_or(0)
506	}
507	
508	/// Every reported damage must be covered by an insured item of its own. The
509	/// office compares the damages it was sent against the policy type by type, so a
510	/// type damaged twice needs two insured items of that type to stand. One
511	/// comparison decides admissibility; how far it falls short decides which
512	/// refusal the claim earns -- a type the policy does not cover at all is refused
513	/// as uninsured, a type covered by too few items as an over-count.
514	fn check_policy_covers_every_damage(
515	    items: &[Item],
516	    incident: &Incident,
517	) -> Result<(), ClaimError> {
518	    let insured = count_by_item_type(items.iter().map(|item| item.item_type.as_str()));
519	    for (item_type, reported) in
520	        count_by_item_type(incident.damages.iter().map(|damage| damage.item_type.as_str()))
521	    {
522	        let insured_of_that_type = insured_count_of(&insured, item_type);
523	        if insured_of_that_type == 0 {
524	            return Err(ClaimError::ItemNotInsured {
525	                item_type: item_type.to_string(),
526	            });
527	        }
528	        if reported > insured_of_that_type {
529	            return Err(ClaimError::MoreDamagesThanInsuredItems {
530	                item_type: item_type.to_string(),
531	            });
532	        }
533	    }
534	    Ok(())
535	}
536	
537	/// What the MHPCO settles on an incident filed against a policy: what the
538	/// incident earns, limited by the cap the policy has left. The office first
539	/// satisfies itself that the claim is admissible at all; an inadmissible claim
540	/// is refused whole, and nothing is paid out on it.
541	pub fn claim(
542	    items: &[Item],
543	    incident: &Incident,
544	    cap_already_consumed: u64,
545	) -> Result<ClaimResult, ClaimError> {
546	    check_every_damage_amount_is_a_loss(incident)?;
547	    check_policy_covers_every_damage(items, incident)?;
548	    Ok(settled_within_cap(
549	        claim_payout(items, incident),
550	        cap_remaining_on(items, cap_already_consumed),
551	    ))
552	}
553	
554	/// What the MHPCO has on record about a customer's dealings so far as it works
555	/// through their scenario: how many contracts they already hold, and how much
556	/// of each policy's cap earlier claims have already drawn down. Both are
557	/// written up as the office goes, and both are read back by later steps.
558	#[derive(Default)]
559	struct ScenarioLedger {
560	    contracts_already_held: u32,
561	    cap_consumed_by_policy: BTreeMap<usize, u64>,
562	}
563	
564	impl ScenarioLedger {
565	    /// Every quote writes a new contract into the customer's record, so the
566	    /// next quote is one further along their history with the office.
567	    fn record_new_contract(&mut self) {
568	        self.contracts_already_held += 1;
569	    }
570	
571	    /// How much of its cap a policy has already paid out on, before this claim.
572	    fn cap_consumed_by(&self, policy: usize) -> u64 {
573	        self.cap_consumed_by_policy.get(&policy).copied().unwrap_or(0)
574	    }
575	
576	    /// A settled payout draws down the cap of the policy it was filed against,
577	    /// leaving that much less for the policy's later claims.
578	    fn record_payout_against(&mut self, policy: usize, payout: u64) {
579	        *self.cap_consumed_by_policy.entry(policy).or_insert(0) += payout;
580	    }
581	}
