583	/// Steps are processed in order: each quote writes a policy a later claim can
584	/// refer to by its step index, and each claim draws down that policy's cap.
585	pub fn process_scenario(scenario: &Scenario) -> Result<Vec<StepResult>, ScenarioError> {
586	    let mut ledger = ScenarioLedger::default();
587	    scenario
588	        .steps
589	        .iter()
590	        .enumerate()
591	        .map(|(position, step)| process_step(scenario, position, step, &mut ledger))
592	        .collect()
593	}
594	
595	/// What one step of a scenario earns, read against and written back into the
596	/// record the office keeps of the customer's dealings so far.
597	fn process_step(
598	    scenario: &Scenario,
599	    position: usize,
600	    step: &Step,
601	    ledger: &mut ScenarioLedger,
602	) -> Result<StepResult, ScenarioError> {
603	    match step {
604	        Step::Quote { items } => {
605	            let premium =
606	                quote_premium(&scenario.customer, ledger.contracts_already_held, items)
607	                    .map_err(ScenarioError::Quote)?;
608	            ledger.record_new_contract();
609	            Ok(StepResult::Quote { premium })
610	        }
611	        Step::Claim { policy, incident } => {
612	            let settled = claim(
613	                insured_items_of(scenario, *policy, position)?,
614	                incident,
615	                ledger.cap_consumed_by(*policy),
616	            )
617	            .map_err(ScenarioError::Claim)?;
618	            ledger.record_payout_against(*policy, settled.payout);
619	            Ok(StepResult::Claim {
620	                payout: settled.payout,
621	                remaining_cap: settled.remaining_cap,
622	            })
623	        }
624	    }
625	}
626	
627	/// The items insured by the policy a quote step created. A claim names its
628	/// policy by the step index of the quote that wrote it, and only a quote step
629	/// already behind it speaks for a policy: the office searches the steps it has
630	/// worked through before this claim, so an index naming a claim step, one past
631	/// the end of the scenario, and one pointing at or ahead of the claim itself all
632	/// name no policy at all and the whole scenario is refused. The office would
633	/// rather refuse a claim it cannot place than settle it against nothing.
634	fn insured_items_of(
635	    scenario: &Scenario,
636	    policy: usize,
637	    claim_position: usize,
638	) -> Result<&[Item], ScenarioError> {
639	    let steps_already_processed = &scenario.steps[..claim_position];
640	    match steps_already_processed.get(policy) {
641	        Some(Step::Quote { items }) => Ok(items),
642	        _ => Err(ScenarioError::NoPolicyAtStep { step: policy }),
643	    }
644	}
